SELECT supplier_id, launch_month, initech_stock_qty, books_price FROM (SELECT supplier_id, DATE_FORMAT(launch_date, 'yyyy-MM') launch_month, SUM(CASE WHEN brand = 'Initech' THEN stock_qty ELSE 0 END) initech_stock_qty, SUM(CASE WHEN category = 'Books' THEN price ELSE 0 END) books_price FROM products GROUP BY supplier_id, DATE_FORMAT(launch_date, 'yyyy-MM')) s WHERE initech_stock_qty > 46;
